#include <stdint.h>

typedef struct { uint64_t s; } Rng;

uint64_t rng_next(Rng *r)
{
    uint64_t x = r->s;
    x ^= x << 13;
    x ^= x >> 7;
    x ^= x << 17;
    return r->s = x;
}

uint64_t rng_below(Rng *r, uint64_t n)
{
    uint64_t limit = UINT64_MAX - UINT64_MAX % n;
    uint64_t x;
    do {
        x = rng_next(r);
    } while (x >= limit);
    return x % n;
}

double rng_double(Rng *r)
{
    return (double)(rng_next(r) >> 11) * (1.0 / 9007199254740992.0);
}

unitTests:
TEST("the exact sequence") { Rng r = {88172645463325252ULL}; CHECK(rng_next(&r) == 8748534153485358512ULL); CHECK(rng_next(&r) == 3040900993826735515ULL); CHECK(rng_next(&r) == 3453997556048239312ULL); }
TEST("below") { Rng r = {7}; int want[] = {3, 0, 3, 1, 4, 1, 1, 0}; for (int i = 0; i < 8; i++) CHECK_EQ((int)rng_below(&r, 6), want[i]); Rng q = {99}; for (int i = 0; i < 1000; i++) CHECK(rng_below(&q, 1) == 0); }
TEST("doubles stay in range") { Rng r = {2026}; double lo = 1, hi = 0, sum = 0; for (int i = 0; i < 10000; i++) { double d = rng_double(&r); CHECK(d >= 0.0 && d < 1.0); if (d < lo) lo = d; if (d > hi) hi = d; sum += d; } CHECK(lo < 0.01); CHECK(hi > 0.99); CHECK_NEAR(sum / 10000, 0.5, 0.02); }
TEST("fair counts") { Rng r = {1}; int c[3] = {0}; for (int i = 0; i < 30000; i++) c[rng_below(&r, 3)]++; for (int k = 0; k < 3; k++) CHECK(c[k] > 9500 && c[k] < 10500); }

